<body>
  <main class="app">
    <header>
      <h1>Voice Consistency Checker</h1>
      <p class="lede">Paste a paragraph, choose the voice traits you want, then get diagnostic flags and a revision brief. No rewriting. No internet. No external files.</p>
    </header>

    <section class="layout">
      <div class="panel">
        <h2>Draft paragraph</h2>
        <label for="draft">Paste or type your paragraph</label>
        <textarea id="draft" placeholder="Paste your draft paragraph here..."></textarea>

        <div class="toolbar">
          <button class="primary" id="analyzeBtn" type="button">Analyze</button>
          <button class="ghost" id="copyBriefBtn" type="button">Copy brief</button>
          <button class="ghost" id="exportTxtBtn" type="button">Export .txt</button>
          <button class="ghost" id="clearBtn" type="button">Clear</button>
        </div>

        <div class="notice">
          This tool only identifies consistency issues. It will not rewrite, paraphrase, or replace your draft.
        </div>
      </div>

      <div class="panel">
        <h2>Target voice traits</h2>
        <div class="trait-grid" id="traitGrid"></div>

        <div style="margin-top: 12px;">
          <label for="customTraits">Custom voice notes</label>
          <input class="small-input" id="customTraits" type="text" placeholder="Example: less salesy, more precise">
          <p class="micro">Custom notes are included in the revision brief, but the score uses the selected traits above.</p>
        </div>

        <div class="toolbar">
          <button class="ghost" id="selectLeanBtn" type="button">Lean preset</button>
          <button class="ghost" id="selectWarmBtn" type="button">Warm preset</button>
          <button class="ghost" id="selectFormalBtn" type="button">Formal preset</button>
          <button class="ghost" id="exportJsonBtn" type="button">Export .json</button>
        </div>
      </div>
    </section>

    <section class="panel" style="margin-top: 14px;">
      <div class="score-card">
        <div class="score-ring" id="scoreRing" style="--score: 0;">
          <div class="score-number" id="scoreNumber">0</div>
        </div>
        <div class="score-copy">
          <h2 id="scoreLabel">Waiting for text</h2>
          <p id="scoreSummary">Paste a paragraph and choose voice traits to start.</p>
        </div>
      </div>

      <div class="stats">
        <div class="stat">
          <strong id="wordCount">0</strong>
          <span>words</span>
        </div>
        <div class="stat">
          <strong id="sentenceCount">0</strong>
          <span>sentences</span>
        </div>
        <div class="stat">
          <strong id="avgSentence">0</strong>
          <span>avg words</span>
        </div>
      </div>

      <h3 class="section-title">Flags</h3>
      <div class="flag-list" id="flags"></div>

      <h3 class="section-title">Revision brief</h3>
      <div class="brief-box" id="briefBox">Your brief will appear here.</div>
